/// Os seis primeiros dígitos hexadecimais do MAC, em minúsculas.
fn oui(mac_address: &str) -> Option<String> {
    let normalized: String = mac_address
        .chars()
        .filter(char::is_ascii_hexdigit)
        .take(6)
        .map(|char| char.to_ascii_lowercase())
        .collect();
    (normalized.len() == 6).then_some(normalized)
}

/// Prefixo dos MACs que o Docker dá aos contêineres.
const DOCKER_PREFIX: &str = "0242";

/// Quantos prefixos a tabela embutida conhece.
#[must_use]
pub fn len() -> usize {
    VENDORS.len()
}

/// MAC de contêiner Docker (`02:42:…`).
#[must_use]
pub fn is_docker(mac_address: &str) -> bool {
    oui(mac_address).is_some_and(|oui| oui.starts_with(DOCKER_PREFIX))
}

/// Fabricante pelo OUI. Um MAC de contêiner Docker é administrado
/// localmente, mas a origem dele é conhecida.
#[must_use]
pub fn lookup_vendor(mac_address: &str) -> Option<&'static str> {
    if is_docker(mac_address) {
        return Some("Docker (contêiner)");
    }
    VENDORS.get(oui(mac_address)?.as_str()).copied()
}

/// MAC administrado localmente (bit `0x02` do primeiro octeto): é o endereço
/// aleatório que celulares e notebooks usam por privacidade — ou de máquina
/// virtual/contêiner. Nunca está na tabela OUI.
#[must_use]
pub fn is_locally_administered(mac_address: &str) -> bool {
    oui(mac_address)
        .and_then(|oui| u8::from_str_radix(&oui[..2], 16).ok())
        .is_some_and(|first| first & 0x02 != 0)
}

#[cfg(test)]
mod tests {
    use super::{is_locally_administered, lookup_vendor};

    #[test]
    fn identifica_fabricantes_de_rede_com_mac_formatado_ou_nao() {
        assert_eq!(
            lookup_vendor("04:18:D6:12:34:56"),
            Some("Ubiquiti Networks")
        );
        assert_eq!(lookup_vendor("000c42abcdef"), Some("MikroTik"));
        assert_eq!(lookup_vendor("00:0B:86:12:34:56"), Some("Aruba Networks"));
    }

    #[test]
    fn reconhece_iot_e_conteiner() {
        assert_eq!(lookup_vendor("5c:cf:7f:00:11:22"), Some("Espressif"));
        assert_eq!(
            lookup_vendor("02:42:ac:11:00:02"),
            Some("Docker (contêiner)")
        );
    }

    #[test]
    fn mac_aleatorio_e_reconhecido() {
        assert!(is_locally_administered("da:a1:19:00:11:22"));
        assert!(is_locally_administered("02:42:ac:11:00:02"));
        assert!(!is_locally_administered("5c:cf:7f:00:11:22"));
        assert!(!is_locally_administered("zz"));
    }

    #[test]
    fn mac_incompleto_nao_e_consultado() {
        assert_eq!(lookup_vendor("00:0b"), None);
    }
}
